#!/usr/bin/env python3
"""
install_stage6e.py - Stage 6: hand the webhook pipeline to ctx.waitUntil() so the 200 goes out at once.

WHY (all measured on the deployed probe Worker, see stage6-findings): FastAPI BackgroundTasks keep the response waiting
until the whole pipeline ends; ctx.waitUntil answers immediately and keeps the work alive for about 30 s after the response
(a 28 s task finished, a 35 s task was cancelled). The probe also showed the request's ctx can travel inside the ASGI env.

WHAT IT CHANGES (4 files, all or nothing, nothing is touched if any check fails):
    src/app/worker_ctx.py            NEW   EnvWithCtx + get_worker_ctx (pure Python)
    src/app/main.py                  REPLACED  `class Default(WorkerEntrypoint)` instead of `Default = asgi.entrypoint(app)`
    src/app/routers/webhook.py       REPLACED  receive_message: ctx.waitUntil when a ctx exists, BackgroundTasks otherwise
    test_stage6_routes.py            REPLACED  updated static/parity checks + new scheduling checks
_process_message, supabase_client, ai_client, meta_client and the firewall are NOT touched.

HOW (from the cf-worker folder):
    cd /workspaces/boltane-workers-poc/files12/cf-worker
    python install_stage6e.py
It refuses (and writes nothing) if one of the three existing files is not exactly the version this chat started from.
"""
import base64, hashlib, py_compile, sys, zlib
from pathlib import Path

FILES = {'src/app/main.py': {'data': '',
                     'old_sha256': 'bb2db54bd5c885aa7ec2513f329289433942bcf1d1b719b8b6821bac370ad5a8',
                     'sha256': '0a885649a8e96284b3d6adf55326fa2e16b817de01b2af35de131f448145865d'},
 'src/app/routers/webhook.py': {'data': '',
                                'old_sha256': '8c64a9e71ab36efdd044eaca977547503afdcf54718f0554e02bfa1adb9e80a7',
                                'sha256': '08e4e076393107198e336e90a6b3032e5cec28754efcb517280eafbd60c3bf70'},
 'src/app/worker_ctx.py': {'data': '',
                           'old_sha256': None,
                           'sha256': '9fdcaca95c2396d444a0547109635fc3ace678de7809ca64dfad529d0f3c7d94'},
 'test_stage6_routes.py': {'data': '',
                           'old_sha256': '1cfed94315c0ac80dd71468bf382b4aea53c8e90f7ffa09a87771afaad59d657',
                           'sha256': '25b78ea3b3c64b37eb704d6dee62399cac8f426f80f65365fd2f6884f2a07996'}}

root = Path.cwd()
if not (root / "wrangler.jsonc").exists() or not (root / "src" / "app" / "main.py").exists():
    sys.exit("This does not look like the cf-worker folder.\nRun:  cd /workspaces/boltane-workers-poc/files12/cf-worker   and try again.")

plan, problems = [], []
for name, info in FILES.items():
    raw = zlib.decompress(base64.b64decode(info["data"]))
    if hashlib.sha256(raw).hexdigest() != info["sha256"]:
        sys.exit(f"FAIL  {name}: embedded data is corrupted (hash mismatch) - nothing written.")
    path = root / name
    if path.exists():
        current = hashlib.sha256(path.read_bytes()).hexdigest()
        if current == info["sha256"]:
            plan.append((name, path, None, "already up to date"))
            continue
        if info["old_sha256"] is None or current != info["old_sha256"]:
            problems.append(f"{name}: differs from the version this change was made against - send me the current file.")
            continue
    plan.append((name, path, raw, "REPLACED" if path.exists() else "CREATED "))

if problems:
    sys.exit("NOTHING WRITTEN.\n  " + "\n  ".join(problems))

failed = False
for name, path, raw, label in plan:
    if raw is None:
        print(f"SKIPPED    {name}   ({label})")
        continue
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(raw)
    try:
        py_compile.compile(str(path), doraise=True, cfile="/tmp/_stage6e_check.pyc")
        note = "compiles"
    except py_compile.PyCompileError as exc:
        note, failed = f"DOES NOT COMPILE: {exc}", True
    print(f"{label}   {name}   {note}")
print()
if failed:
    sys.exit("FAILED - see above. (git checkout the files to go back.)")
print("Done. Next (activate the tests venv first):")
print("    source ~/venv-tests/bin/activate")
print("    PYTHONPATH=tooling/local-test-support:src python test_stage6_routes.py")
print("    python test_stage5_firewall.py")
print("    python test_stage6_meta_sim.py")
print("then deploy:  uv run pywrangler deploy   and run test_stage6_deployed.py check / deliver (see the chat).")
